import{_ as n,o as a,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Dependencies and Contracts","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/dependencies-and-contracts.md","filePath":"architecture/dependencies-and-contracts.md","lastUpdated":null}'),s={name:"architecture/dependencies-and-contracts.md"};function r(o,e,c,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="dependencies-and-contracts" tabindex="-1">Dependencies and Contracts <a class="header-anchor" href="#dependencies-and-contracts" aria-label="Permalink to &quot;Dependencies and Contracts&quot;">​</a></h1><p><strong>Status:</strong> Approved foundation<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="dependency-direction" tabindex="-1">Dependency direction <a class="header-anchor" href="#dependency-direction" aria-label="Permalink to &quot;Dependency direction&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>domain and shared application contracts  &lt;-  infrastructure implementations</span></span>
<span class="line"><span>                    ^</span></span>
<span class="line"><span>                    |</span></span>
<span class="line"><span>          application composition</span></span></code></pre></div><p>The following rules are strict:</p><ol><li>Domains MUST NOT import <code>internal/infrastructure</code>.</li><li>A domain defines the smallest interfaces required to perform its work.</li><li>Infrastructure implements those interfaces and translates external representations at the boundary.</li><li>Only application composition chooses concrete implementations.</li><li>A domain MUST NOT manipulate another domain&#39;s state or call its internal services.</li><li>Cross-domain work uses an explicitly designed command, event, or approved shared contract.</li><li>Implementation difficulty is not permission to violate a boundary.</li></ol><p>Broker messages, database rows, SDK response types, and configuration DTOs MUST NOT leak into domain models.</p><h2 id="commands-and-events" tabindex="-1">Commands and events <a class="header-anchor" href="#commands-and-events" aria-label="Permalink to &quot;Commands and events&quot;">​</a></h2><ul><li>An event records something that happened and is owned by its publishing domain.</li><li>A command requests an action and is owned by the domain expected to handle it.</li><li>Consumers do not redefine an event&#39;s meaning.</li><li>Senders obey the receiving domain&#39;s command contract.</li><li>There is no generic package containing unrelated application messages.</li></ul><h2 id="event-bus" tabindex="-1">Event bus <a class="header-anchor" href="#event-bus" aria-label="Permalink to &quot;Event bus&quot;">​</a></h2><p><code>internal/eventbus</code> is an approved shared application contract. It defines only the messaging behaviour Archie requires, including publication, subscription, delivery outcomes, and required lifecycle semantics.</p><p>It MUST remain broker-neutral. NATS subjects, JetStream configuration, consumer groups, acknowledgements, reconnection, and serialization belong under <code>internal/infrastructure/eventbus/nats</code> unless Archie explicitly requires a semantic guarantee in the shared contract.</p><p>Message schemas stay with their owning domains. The event bus transports messages; it does not own their meaning.</p><h2 id="wire-contracts-and-generation" tabindex="-1">Wire contracts and generation <a class="header-anchor" href="#wire-contracts-and-generation" aria-label="Permalink to &quot;Wire contracts and generation&quot;">​</a></h2><p>Canonical worker and service wire contracts and their authoritative generation inputs are owned by the domain or capability that defines their meaning. They MUST NOT be centralized in <code>internal/infrastructure/spec</code> or another generic schema package.</p><p>Infrastructure owns:</p><ul><li>generic contract-generation machinery;</li><li>transport-specific adapters and generated implementations;</li><li>RPC, REST, NATS, and other external encoding and delivery concerns.</li></ul><p>For example, agent-worker requests and results belong to task execution. Subprocess, NATS, or HTTP representations are infrastructure implementations of that contract. The same rule applies independently to forge, persistence, workspace, and other service contracts.</p>`,18)])])}const h=n(s,[["render",r]]);export{m as __pageData,h as default};
